import{z as s,x as d,o as t,c as m,q as o,j as r,D as a,d as l,s as i,S as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"token 计量与限流","description":"","frontmatter":{"title":"token 计量与限流","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/token-ratelimit.md","filePath":"llm/token-ratelimit.md","lastUpdated":1791413859000}'),p={name:"llm/token-ratelimit.md"};function A(c,e,B,P,h,k){const n=d("Mermaid");return t(),m("div",null,[e[2]||(e[2]=o('<h1 id="token-计量与限流" tabindex="-1">token 计量与限流 <a class="header-anchor" href="#token-计量与限流" aria-label="Permalink to &quot;token 计量与限流&quot;">​</a></h1><div class="epigraph"><p>配额若按请求个数，短补全与万 token 写作会被当成同一件事；计量单位必须是 tokenizer 之后的 token，限流才能贴近算力与账单。</p><footer>—— 对照云厂商 API 的 RPM / TPM 配额与服务端在 encode 之后、prefill 之前的闸门</footer></div><p><a href="/llm/adapter-hot-swap">上一课</a>把热更新写成迭代边界上的指针切换：在途请求钉旧页，新请求钉新页；适配器版本必须进入 KV 缓存键。版本对了，一次「请求」的代价仍可以从几百 FLOPs 到数万长度前填再加数千步 decode。HTTP 429 按请求计数会系统性偏向重请求。缺口是把计量钉在与引擎相同的 tokenizer 上：同时报 RPM 与 TPM，并做预扣–结算。本课写突发、拒绝与分项；账单里缓存折扣见 <a href="/llm/prompt-cache-billing">提示缓存计费</a>。不编造一篇 token rate limit 的会议论文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>按请求限流会系统性偏向重请求：同一 RPM 下，有人拿 128k 上下文做 RAG，有人做三字补全，GPU 与 KV 被前者吃光，后者在队列里看 429。按字符或字节限流对中文、代码、emoji 的误差很大，且与模型内部长度对不上——闸门必须发生在 <a href="/llm/serving-tokenizer-cost">encode</a> 之后。按「估算 token」用 <code>len/4</code> 一类规则，会在中文上低估、在重复标点上高估，配额变成随机数。</p><p><span class="marginnote">数字实例：配额 10K TPM、窗口 60 秒。一条 8K token 的 RAG 提示一次就吃掉八成 TPM，再来三条同款这一分钟就见底——若按请求数计，这三条和「三字补全」待遇相同。按 token 计量，才让每类请求付自己真实的算力价钱。</span></p><p>输出侧更麻烦。到达时只知道 <code>max_tokens</code> 上限，不知道真实结束步。若只在结束后扣配额，用户可以先把 KV 池打满再 429，保护来不及。若按 <code>max_tokens</code> 预扣，短回复会长期占着额度，看起来像限流过严。需要预扣-结算，而不是只选一端。</p><h3 id="rpm-与-tpm-管的不是同一类事故" tabindex="-1">RPM 与 TPM 管的不是同一类事故 <a class="header-anchor" href="#rpm-与-tpm-管的不是同一类事故" aria-label="Permalink to &quot;RPM 与 TPM 管的不是同一类事故&quot;">​</a></h3><p>RPM 挡住的是连接与调度器唤醒：极短请求也能把前端、鉴权、连续批的成员更新打满。TPM 挡住的是前填 FLOPs、decode 带宽与 KV 字节。只有 RPM 时，一条超长提示合法地打穿全卡；只有 TPM 时，每秒成千上万条空消息仍能把控制面打死。两者要同时存在，拒绝原因要分开计数，否则会把「提示太长」与「QPS 太高」混成同一个告警。</p>',9)),(t(),r(E,null,{default:a(()=>[i(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%A4%E4%B8%AA%E6%97%8B%E9%92%AE%20%E5%90%84%E6%8C%A1%E4%B8%80%E7%B1%BB%E4%BA%8B%E6%95%85%22%5D%20--%3E%20RPM%5B%22RPM%3A%20%E6%AF%8F%E5%88%86%E9%92%9F%E8%AF%B7%E6%B1%82%E6%95%B0%22%5D%0A%20%20Q%20--%3E%20TPM%5B%22TPM%3A%20%E6%AF%8F%E5%88%86%E9%92%9F%20token%20%E6%95%B0%22%5D%0A%20%20RPM%20--%3E%20C1%5B%22%E6%8C%A1%E6%8E%A7%E5%88%B6%E9%9D%A2%E8%BF%87%E8%BD%BD%3A%20%E9%89%B4%E6%9D%83%2F%E8%B0%83%E5%BA%A6%E5%94%A4%E9%86%92%22%5D%0A%20%20TPM%20--%3E%20C2%5B%22%E6%8C%A1%E7%AE%97%E5%8A%9B%E8%BF%87%E8%BD%BD%3A%20%E5%89%8D%E5%A1%AB%20FLOPs%2FKV%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20C1%20--%3E%20BOTH%5B%22%E5%90%8C%E6%97%B6%E8%AE%BE%20%E6%8B%92%E7%BB%9D%E5%8E%9F%E5%9B%A0%E5%88%86%E5%BC%80%E8%AE%A1%E6%95%B0%22%5D%0A%20%20C2%20--%3E%20BOTH%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><span class="marginnote"><code>usage.prompt_tokens</code> / <code>completion_tokens</code> 必须与闸门同源。网关用 tiktoken、引擎用 SentencePiece，账单与 429 会对不上，客诉无法仲裁。兼容层应在同一进程、同一词表上计数，见 <a href="/llm/openai-compat-api">OpenAI 兼容协议</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令请求 \\(r\\) 的提示 token 数为 \\(n\\)，声明的最大输出为 \\(m_{\\max}\\)，实际输出为 \\(m\\)。输入侧在 encode 之后立刻计量 \\(n\\)；输出侧先预扣 \\(m_{\\max}\\)（或按产品设的默认上限），结束时按 \\(m\\) 结算，释放差额。窗口 \\(T\\)（通常 60 s）内租户 \\(u\\) 的消耗为</p> \\[C_{\\mathrm{in}}(u)=\\sum n,\\qquad C_{\\mathrm{out}}(u)=\\sum m,\\qquad C_{\\mathrm{req}}(u)=\\#\\{r\\}. \\]<p>超限当且仅当任一分项超过配额。实现上常用令牌桶：桶容量等于突发额度，每秒按持续速率加水。突发允许短时超过平均值，但桶空即 429，并带 <code>Retry-After</code> 或等价头。不要用「每分钟清零计数器」当唯一算法：边界上会出现第 59 秒打满、第 0 秒再打满的双倍尖刺。</p><p><span class="marginnote">「令牌桶」翻译成大白话：给配额装一个滴水的水龙头——桶按固定速率进水（持续额度），每个请求取走一枚，桶的容量就是允许的突发量。它比「每分钟清零」好在没有边界漏洞：清零式在第 59 秒和第 60 秒能连打两轮满额，令牌桶的余额始终连续变化。</span></p><p>优先级与配额成对。付费档 TPM 高、突发大；免费档 TPM 低、可抢占。过载时先拒低档，而不是大家一起排队到 <a href="/llm/serving-slo">SLO</a> 集体违约，见 <a href="/llm/priority-sla">优先级</a>。预填与 decode 可以分开记账：输入 TPM 打满时拒新的长提示，但允许已在生成的请求把输出桶用完——否则会在句子中间 429，流式协议更难处理。产品若必须中途停下，应发明确的 finish reason，而不是切断 TCP。</p><h3 id="预扣要防占坑" tabindex="-1">预扣要防占坑 <a class="header-anchor" href="#预扣要防占坑" aria-label="Permalink to &quot;预扣要防占坑&quot;">​</a></h3><p>恶意或粗心的客户端把 <code>max_tokens</code> 开到上下文上限，预扣会把整分钟的输出 TPM 锁死，别人进不来。对策：对 \\(m_{\\max}\\) 设产品上限；预扣按 \\(\\min(m_{\\max}, m_{\\mathrm{budget}})\\)；对长时间占坑的连接做空闲超时。工具调用多轮时，每一轮都是新的 \\(n\\) 与 \\(m\\)，配额按轮累加，不要只在会话开始扣一次。</p><p>流式计量：每吐出 \\(k\\) 个 token 向桶扣一次，避免结束才发现已经超了两个数量级。扣的粒度太细会打爆计数器；太粗又失去保护。常见折中是每步或每 8/16 token 批扣，与引擎迭代对齐。</p>',10)),(t(),r(E,null,{default:a(()=>[i(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20ENC%5B%22encode%20%C2%B7%20%E5%90%8C%E4%B8%80%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20ENC%20--%3E%20IN%7B%22%E8%BE%93%E5%85%A5%20TPM%20%2F%20RPM%22%7D%0A%20%20IN%20--%3E%7C%E8%B6%85%7C%20R429%5B%22429%20%2B%20Retry-After%22%5D%0A%20%20IN%20--%3E%7C%E8%BF%87%7C%20RES%5B%22%E6%8C%89%20max_tokens%20%E9%A2%84%E6%89%A3%E8%BE%93%E5%87%BA%22%5D%0A%20%20RES%20--%3E%20RUN%5B%22prefill%20%2F%20decode%22%5D%0A%20%20RUN%20--%3E%20SET%5B%22%E6%8C%89%E5%AE%9E%E9%99%85%20m%20%E7%BB%93%E7%AE%97%E5%B9%B6%E9%87%8A%E6%94%BE%E5%B7%AE%E9%A2%9D%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>token 近似于工作量，但不是恒等。前填成本随 \\(n\\) 近似二次（注意力）加线性（FFN）；decode 每步扫权重，与 \\(m\\) 近似线性，但步墙钟还被批大小与 KV 长度调制。因此 TPM 是<strong>计费与公平</strong>的单位，不是精确的 GPU 秒。同一 TPM 下，全是长前填与全是长 decode 对硬件的伤害不同；精细运营应再按长度桶拆配额，或对超长提示走单独队列。</p><h3 id="闸门必须在分配-kv-之前" tabindex="-1">闸门必须在分配 KV 之前 <a class="header-anchor" href="#闸门必须在分配-kv-之前" aria-label="Permalink to &quot;闸门必须在分配 KV 之前&quot;">​</a></h3><p>限流点要放在 KV 分配之前。先准入再 429，空洞已经占上了，保护失败。正确顺序：鉴权 → encode → 查桶 → 拒或预扣 → 进调度器。分布式网关要用同一后端计数（Redis 一类）或按租户一致性哈希到固定限流分片，否则每个副本各有一个桶，配额被乘以副本数。</p><p><span class="marginnote">初学者容易把闸门放在调度器之后，「都放进来了再挑」。但那一刻 KV 已经分配、显存空洞已经挖好，429 发出去也收不回资源——保护必须发生在分配之前。分布式部署还有个隐蔽坑：每个网关副本各记各的桶，10 个副本等于配额悄悄翻了 10 倍。</span></p><p><span class="marginnote">缓存命中的提示 token 还算不算 TPM，是产品条款。许多云 API 仍把缓存 token 计入速率上限，只在<strong>账单</strong>上打折。限流与计费拆开写，避免「缓存省钱却仍然 429」的意外，细节见提示缓存计费专文。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多模态：图像/音频被编成许多 token，必须用模型卡上的计数规则，不能按文件字节。思维链若对用户隐藏，对外计量要声明是否含内部 token——隐藏却计费会引发客诉；隐藏且不计费会变成一条绕过 TPM 的通道。投机解码拒绝的草稿不应计入用户输出，但算力已经花了；goodput 与 TPM 不是同一张表。</p><p>不要在客户端「自行估算」代替服务端闸门。SDK 可以提示剩余配额，权威在服务端。时钟回拨、重试未去重会把同一请求扣两次或零次：重试必须带幂等键，限流统计按用户可见的一次尝试。跨区域的桶是否共享，决定用户能不能靠换区翻倍配额，见 <a href="/llm/multi-region-failover">多区域故障转移</a>。</p><p><span class="marginnote">429 的响应体应可机器读：哪个维度超了、当前窗口剩余、建议等待。只返回字符串 “rate limit” 会迫使客户端盲退避，把尾延迟写得更肥。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计量单位是与引擎同一词表的 token；RPM 与 TPM 同时要，分别挡住控制面与算力。</li><li>输出按 <code>max_tokens</code> 预扣、按实际 \\(m\\) 结算；流式批扣，防止占坑与事后超支。</li><li>令牌桶比整分钟清零更能打突发；分布式必须共享桶或按租户分片。</li><li>闸门在 encode 之后、KV 分配之前；<code>usage</code> 与 429 同源。</li><li>缓存折扣、思维链可见性、多模态计数都是条款，不是算法细节。</li><li>出处：对照 OpenAI / Anthropic 等公开 API 的 RPM·TPM 模型与令牌桶限流实践；无单独经典论文名。</li></ul>',12))])}const u=s(p,[["render",A]]);export{T as __pageData,u as default};
